import{_ as a,o as i,c as e,a0 as d}from"./chunks/framework.DCluYYrN.js";const v=JSON.parse('{"title":"FoxSu — 内核 root，界面重生","titleTemplate":false,"description":"","frontmatter":{"layout":"home","title":"FoxSu — 内核 root，界面重生","titleTemplate":false,"hero":{"name":"FoxSu","text":"内核 root，界面重生","tagline":"Root 留在内核里，界面从头写过。五套皮肤、13 种底栏、一个能改到每个像素的定制中心——你每天都要打开的那个 App，终于有了自己的样子。","image":{"src":"/logo.png","alt":"FoxSu"},"actions":[{"theme":"brand","text":"开始安装","link":"/zh_CN/guide/installation"},{"theme":"alt","text":"在 GitHub 查看","link":"https://github.com/Cmry-mlc/FoxSu"}]}},"headers":[],"relativePath":"zh_CN/index.md","filePath":"zh_CN/index.md"}'),l={name:"zh_CN/index.md"};function n(c,s,t,p,o,r){return i(),e("div",null,[...s[0]||(s[0]=[d('<div class="fs-home"><section class="fs-section"><div class="fs-kpis"><div class="fs-kpi"><b>KernelSU</b><span>内核与 ksud 来自上游</span></div><div class="fs-kpi"><b>5 套</b><span>可切换的界面皮肤</span></div><div class="fs-kpi"><b>13 种</b><span>底栏胶囊样式</span></div><div class="fs-kpi"><b>API 37</b><span>Android 12 及以上</span></div></div></section><section class="fs-section"><span class="fs-eyebrow">Skins</span><h2 class="fs-title">五套皮肤，同一份功能</h2><p class="fs-lede">在「设置 → 界面风格」里切换，所有页面同步生效。不是换张壁纸，是五种排版语言。</p><div class="fs-skins"><article class="fs-skin fs-skin--redesign"><div class="demo"><span></span><span></span><span></span></div><div class="meta"><h3>Redesign</h3><p>玻璃卡片 + 胶囊底栏，信息密度最高，默认皮肤</p></div></article><article class="fs-skin fs-skin--editorial"><div class="demo"><span></span><span></span><span></span></div><div class="meta"><h3>Editorial</h3><p>纸面底色、墨线分隔、衬线标题，杂志排版</p></div></article><article class="fs-skin fs-skin--pages"><div class="demo"><span></span><span></span><span></span></div><div class="meta"><h3>Pages</h3><p>大标题 + 分区块列表，大留白，适合单手浏览</p></div></article><article class="fs-skin fs-skin--glass"><div class="demo"><span></span><span></span><span></span></div><div class="meta"><h3>Glass</h3><p>液态玻璃，通透卡面配浅色高光</p></div></article><article class="fs-skin fs-skin--nocturne"><div class="demo"><span></span><span></span><span></span></div><div class="meta"><h3>Nocturne</h3><p>暗夜霓虹，深色优先，霓虹描边</p></div></article></div></section><section class="fs-section"><span class="fs-eyebrow">Navigation</span><h2 class="fs-title">底栏不再跟皮肤绑死</h2><p class="fs-lede">13 种胶囊样式全局可选。侧边抽屉模式会自动为每个页面让出左侧空间，内容不会被胶囊压住。</p><div class="fs-pills"><span class="fs-pill is-active">原有胶囊</span><span class="fs-pill">展开药丸</span><span class="fs-pill">侧边抽屉</span><span class="fs-pill">流光光标</span><span class="fs-pill">描边霓虹</span><span class="fs-pill">方块卡片</span><span class="fs-pill">渐变实底</span><span class="fs-pill">顶指示条</span><span class="fs-pill">浮起圆片</span><span class="fs-pill">纸面墨线</span><span class="fs-pill">白色药丸</span><span class="fs-pill">液态药丸</span><span class="fs-pill">暗夜霓虹</span></div></section><section class="fs-section"><span class="fs-eyebrow">Customization</span><h2 class="fs-title">定制中心</h2><p class="fs-lede">所有外观项都接真实设置并即时生效，不需要重启。</p><div class="fs-grid"><div class="fs-card"><div class="fs-dot" style="background:linear-gradient(135deg,#f58ba8,#f7a98c);"></div><h3>壁纸</h3><p>选取、拖动裁剪、缩放、压暗，也可以彻底关掉全局背景图。</p></div><div class="fs-card"><div class="fs-dot" style="background:linear-gradient(135deg,#f5ce7e,#a8d8a0);"></div><h3>卡面配图</h3><p>主页大卡、四张 KPI 卡、每个模块卡都能单独配图并调节透明度。</p></div><div class="fs-card"><div class="fs-dot" style="background:linear-gradient(135deg,#8fc9e8,#b49be0);"></div><h3>卡面配色</h3><p>全局取色加单卡覆盖，透明度独立可调，还有一键七彩卡片。</p></div><div class="fs-card"><div class="fs-dot" style="background:linear-gradient(135deg,#b49be0,#f58ba8);"></div><h3>字体</h3><p>系统默认、衬线、等宽、手写圆体，也可以导入自己的字体文件。</p></div><div class="fs-card"><div class="fs-dot" style="background:linear-gradient(135deg,#a8d8a0,#8fc9e8);"></div><h3>标题与图标</h3><p>主页顶部标题可自定义，四套狐狸图标随系统主题切换深浅。</p></div><div class="fs-card"><div class="fs-dot" style="background:linear-gradient(135deg,#f7a98c,#f5ce7e);"></div><h3>圆角与光感</h3><p>圆角、不透明度、图标造型、沉浸光感、液态玻璃，逐项可调。</p></div></div></section><section class="fs-section"><span class="fs-eyebrow">Root</span><h2 class="fs-title">真正干活的部分，还在内核里</h2><p class="fs-lede">su、白名单、App Profile、模块挂载、sucompat 全部由内核模块与 ksud 提供。管理器只是那层你看得见的皮。</p><div class="fs-grid"><div class="fs-card"><div class="fs-dot" style="background:linear-gradient(135deg,#f58ba8,#b49be0);"></div><h3>白名单授权</h3><p>只有被允许的应用能拿到 su，其余应用感知不到 root 存在。</p></div><div class="fs-card"><div class="fs-dot" style="background:linear-gradient(135deg,#8fc9e8,#a8d8a0);"></div><h3>App Profile</h3><p>按 uid 设定 su 的 uid、gid、groups、capabilities 与 SELinux 上下文，策略可存成模板批量套用。</p></div><div class="fs-card"><div class="fs-dot" style="background:linear-gradient(135deg,#f5ce7e,#f58ba8);"></div><h3>模块仓库</h3><p>内置在线索引，浏览、搜索、查看详情并直接安装。卸载后还能撤销。</p></div><div class="fs-card"><div class="fs-dot" style="background:linear-gradient(135deg,#b49be0,#8fc9e8);"></div><h3>Kernel umount</h3><p>在内核层卸载模块，用户态看不到挂载痕迹，配合隐藏 SELinux 修改。</p></div><div class="fs-card"><div class="fs-dot" style="background:linear-gradient(135deg,#a8d8a0,#f5ce7e);"></div><h3>SU Log</h3><p>授权、拒绝等 root 事件写入 sulog，可直接在管理器里翻阅。</p></div><div class="fs-card"><div class="fs-dot" style="background:linear-gradient(135deg,#f7a98c,#b49be0);"></div><h3>安装与诊断</h3><p>单屏安装向导、独立刷写页、崩溃日志、软重启，改完设置不必等开机动画。</p></div></div></section><section class="fs-cta"><h2>先有内核，才有 root</h2><p>只安装 APK 不会获得 root，设备内核必须先包含 FoxSu / KernelSU 驱动。支持 GKI 2.0（内核 5.10+），旧内核需要自行编译。</p><div class="fs-actions"><a class="VPButton medium brand" href="https://github.com/Cmry-mlc/FoxSu/releases">下载管理器 APK</a><a class="VPButton medium alt" href="./guide/installation.html">阅读安装指南</a></div></section></div>',1)])])}const h=a(l,[["render",n]]);export{v as __pageData,h as default};
